-- Atualizar gallon_stock com os valores corretos (calculados dinamicamente)
-- Galão 1: 347,69L comprados - 340,28L usados = 7,41L → 741 centésimos
UPDATE gallon_stock SET stock_liters = 741 WHERE gallon_number = 1;

-- Galão 2: 100L comprados - 100L usados = 0L
UPDATE gallon_stock SET stock_liters = 0 WHERE gallon_number = 2;

-- Galão 3: 50L comprados - 37,37L usados = 12,63L → 1263 centésimos
UPDATE gallon_stock SET stock_liters = 1263 WHERE gallon_number = 3;

-- Confirmar
SELECT gallon_number, stock_liters, ROUND(stock_liters/100, 2) as estoque_L FROM gallon_stock ORDER BY gallon_number;

